def MAX_SAFE_DECIMAL(): from decimal import Decimal return [ MinValueValidator(Decimal('0.00')), MaxValueValidator(Decimal('999999999999999999999999999999999999999999999999999999999999999.999999999999999999999999999999')) ]
def defaulted_decimal(md:int=12, dp:int=2, df:str='0.00', **kwargs:Dict[str,Any]) -> models.DecimalField: from decimal import Decimal return models.DecimalField(max_digits=md, decimal_places=dp, default=Decimal(df), validators=[MAX_SAFE_DECIMAL], **kwargs)
def VALID_MYSQL_MIN_DATE(v): from datetime import date if v < date(1000, 1, 1): logger.warn(f'Date lower than valid passed: {v}') raise ValidationError('Date must not be before 1000-01-01') if v > date(9999, 12, 31): logging.warn(f'Date highter than valid passed: {v}') raise ValidationError('Date must not be after 9999-12-31')
def uuid_def_primary(pk: bool = True, edit: bool = False) -> Dict[str, Union[str, bool]]: return { 'primary_key': pk, 'max_length': 36, 'default': uuid.uuid4, 'editable': edit }
def def_char_field(voidable: bool = False, **kwargs: Dict[str, Any]) -> models.CharField: if not voidable: return models.CharField(max_length=254, **kwargs) return models.CharField(max_length=254, **VOID, **kwargs)
def def_decimal_field(kwargs: Dict[str, Any]) -> models.DecimalField: return models.CharField(max_digits=10, decimal_places=2, **kwargs)
def def_user_creation(related_name='', lazy: bool = True, **kwargs: Dict[str, Any]) -> models.ForeignKey: from ..individuals.user import User return models.ForeignKey('User' if lazy else User, on_delete=models.SET_NULL, null=True, related_name=related_name, **kwargs)
from typing import Any, Union, Dict from django.contrib import messages from django.http import (HttpRequest, HttpResponseRedirect, HttpResponsePermanentRedirect, JsonResponse) from django.shortcuts import redirect from ....configs.messages_templates import get_exception_class_message from .http import get_redirect_url import logging error_logger = logging.getLogger(__name__) def default_permission_denial(request: HttpRequest, err: Any, ref: str = '#UNDEFINED_REFERENCE', logger: logging.Logger = error_logger, redirect_path: str = '/', auto_redirect: bool = True, json: Dict[str, Any] = None) -> Union[HttpResponseRedirect, HttpResponsePermanentRedirect, JsonResponse, None]: from django.core.exceptions import PermissionDenied logger.error(f'{ref} denied permission: {err}') messages.error(request, get_exception_class_message(PermissionDenied, ref)) if json: return JsonResponse({'error': 'Permission denied.'}, status=401) return redirect(get_redirect_url(request, redirect_path)) if auto_redirect else None
def default_undefined_exception(request: HttpRequest, err: Any, ref: str = '#UNDEFINED_REFERENCE', logger: logging.Logger = error_logger, redirect_path: str = '/', auto_redirect: bool = True, json: Dict[str, Any] = None, status: int = 500) -> Union[HttpResponseRedirect, HttpResponsePermanentRedirect, JsonResponse, None]: logger.error(f'{ref} raised an undefined error: {err}') messages.error(request, f'An undefined error was raised: {err}') if json: return JsonResponse({'error': json}, status=status) return redirect(get_redirect_url(request, redirect_path)) if auto_redirect else None
from typing import Any, List, Union, Dict from django.contrib import messages from django.core.exceptions import PermissionDenied from django.db.models import BaseManager from django.http import HttpRequest from ....configs.messages_templates import get_exception_class_message from ....Models.individuals.user import User import logging from logging import Logger security_logger = logging.getlogger(__name__) def permission_required_custom(perm: str, logger: Logger): """ Custom decorator to check if the current user holds a particular permission. If not, an error message is flashed, the issue is logged, and PermissionDenied is raised. """ def decorator(view_func): def _wrapped_view(request: HttpRequest, *args, **kwargs): if not request.user.has_perm(perm): messages.error(request, get_exception_class_message(PermissionDenied)) logger.warning("User %s lacks permission: %s", request.user, perm) raise PermissionDenied("Permission Denied by Permission Requirement") return view_func(request, *args, **kwargs) return _wrapped_view return decorator
def email_validation(email: str, manager: BaseManager[Any], excludes: Union[Dict[str, Any], None]) -> List[str]: from django.core.exceptions import ValidationError from django.core.validators import validate_email errors = [] try: validate_email(email) except ValidationError: security_logger.warn(f'Email validation for {email} failed') errors.append('Invalid email address.') clamped = manager.filter(email=email).exclude(**excludes) if excludes and excludes.items() else manager.filter(email=email) if email and clamped.exists(): errors.append('A lead with this email already exists.') return errors
def user_id_validation(data: dict, manager: Union[BaseManager[Any], str], filters: Dict[Any]) -> List[str]: errors = [] uid = data.get('user_id') if not uid: errors.append('Assignee is required.') else: try: manager = User.objects if manager == 'users' else manager if isinstance(manager, User): if not manager.filter(pk=uid, **filters).exists(): errors.append('Selected user is invalid.') else: if not manager.filter(user_id=uid, **filters).exists(): errors.append('Selected user is invalid') except ValueError as e: errors.append(f'Assignee was invalidated: {e}') except Exception as e: errors.append(f'As unkown error occurred while attempting to validate the user id: {e}') if errors: security_logger.warn(f'Attemp to validate user with id {uid or '## UNDEFINED ID'} failed') return errors

suggestions.spacing:
- Print width should be 80;
- Tab width should be 2;
- Remove trailing white space if present;

general.errors:
- If any catch does not have logging method call (e.g.: console.error in JS, print in Python), include it and add a templated string to detail its name and message
- Include more try/catch (or try/except) (or .catch for Fetch APIs in JS) blocks if you deem necessary
- ALWAYS wrap api calls (like fetch, axios) or related calls within a try/catch or try/except;
- Destructurings should NEVER happen right away. The response should always be tested for truthish first.
- Be defensive using opitional chaining and coalescing operators to avoid null pointer errors;
- The messages logged for the user in toasts or modals should ONLY be the error messages and, if absolutely demanding, the status, never more details than that;
- The message in the console should not describe the function, but the Method that failed + what was the task to be done via this call (ex.: Failed to PUT for employees: ...(error data));
- DO NOT throw errors in the catch block unless explicitly asked to;

instructions.indentation:
- NEVER use more than one whitespace to separate arguments in the same line
- Keep an indentation pattern that allows me to fold and unfold easily the blocks, statements, values for the keys in dictionaries and elements in an ArrayLike:

			- Python:
							'es': '''text text text
											text text text'''


			key: {
				value: `text text text
								text text text`
			}

- Throughout our session, suggest user snippets templates if you keep finding repetitive patterns of code generations (with an already defined json for saving it);

python.strict:
- Always include type hinting;
- Include useful and detailed server logging;
- Include proper error handling, treating the different kinds of possible exceptions;
- If the method is critical (like financial procedures), implement rollback and ACID strategies, with logging associated;
- If the method has severe complexity, consider implementing design patterns like Strategy or Observer;
